/* Ajuste óptico de importes exclusivamente en Wallet PC.
   Primero respeta el tamaño diseñado; reduce solo cuando el valor real no cabe. */
function vWalletPcFitMoney(){
 const root=document.querySelector('main.vWalletPc-world .vWalletPc');
 if(!root)return;
 const targets=root.querySelectorAll(
  '.vWalletPc-stat strong,.vWalletPc-stat small,'+
  '.vWalletPc-limit > strong,.vWalletPc-limit > small,.vWalletPc-limit-row > b,'+
  '.vWalletPc-return .v371-return-tile strong,'+
  '.vWalletPc-cuts button b,.vWalletPc-chart-total strong,.vWalletPc-recent-list button > b'
 );
 for(const el of targets){
  const txt=(el.textContent||'').trim();
  if(!txt||txt==='—')continue;
  el.style.removeProperty('font-size');
  el.style.setProperty('white-space','nowrap','important');
  el.style.setProperty('overflow-wrap','normal','important');
  el.style.setProperty('max-width','100%','important');
  const width=el.clientWidth;
  const original=parseFloat(getComputedStyle(el).fontSize);
  if(!width||!original)continue;
  let measured=el.scrollWidth;
  if(measured<=width+1)continue;
  // Una reducción proporcional evita truncamiento y no cambia el dato original.
  const floor=txt.includes('RD$')||txt.includes('US$')?12:13;
  let size=Math.max(floor,Math.min(original,original*(width-3)/measured));
  el.style.setProperty('font-size',size.toFixed(2)+'px','important');
  measured=el.scrollWidth;
  if(measured>width+1&&size>floor){
   size=Math.max(floor,size*(width-2)/measured);
   el.style.setProperty('font-size',size.toFixed(2)+'px','important');
  }
 }
}
window.addEventListener('resize',()=>requestAnimationFrame(vWalletPcFitMoney));

